async page=>{const ctx=await page.context().browser().newContext({viewport:{width:1200,height:900}});const p=await ctx.newPage();await p.goto('https://micahhoang.com/index');await p.waitForTimeout(1700);const list=await p.evaluate(()=>[...document.querySelectorAll('.idx-year-group')].flatMap(g=>[...g.querySelectorAll('.idx-list-row-grid')].map(e=>({year:g.querySelector('.idx-year-label')?.textContent.trim(),title:e.querySelector('.idx-flip-copy')?.textContent.trim(),industry:e.querySelector('.idx-list-industry')?.textContent.trim(),services:e.querySelector('.idx-list-discipline')?.textContent.trim(),url:e.href||e.querySelector('a')?.href}))));await p.locator('.idx-view-toggle-option').filter({hasText:'Grid'}).click();await p.waitForTimeout(800);const grid=await p.evaluate(()=>[...document.querySelectorAll('.idx-grid-card')].map(e=>({title:e.querySelector('.idx-grid-card-link')?.getAttribute('aria-label'),url:e.querySelector('a')?.href,image:e.querySelector('video')?.poster||e.querySelector('img')?.currentSrc||e.querySelector('img')?.src,services:[...e.querySelectorAll('.idx-grid-card-tag')].map(t=>t.textContent)})));const height=await p.evaluate(()=>{return{taxonomy:document.querySelector('.idx-taxonomy-shell')?.getBoundingClientRect().height}});await ctx.close();return {list,grid,height}}
